def report(target,total,failed):
    target=target.strip().lower()
    if not target or total<0 or failed<0 or failed>total:
        return "Invalid"
    rate=0 if total==0 else failed/total*100
    if failed>=10:
        level="Alert"
    elif failed>=5:
        level="Watch"
    else:
        level="Normal"
    return f"Target: {target}\nFailure rate: {rate:.2f}%\nLevel: {level}"
target=input()
total=int(input())
failed=int(input())
print(report(target,total,failed))
